CREATE TABLE IF NOT EXISTS `exercises` (`id` TEXT NOT NULL, `nameEn` TEXT NOT NULL, `nameZh` TEXT NOT NULL, `bodyPart` TEXT NOT NULL, `equipment` TEXT NOT NULL, `target` TEXT NOT NULL, `muscleGroup` TEXT NOT NULL, `secondaryMuscles` TEXT NOT NULL, `instructionsZh` TEXT NOT NULL, `instructionsEn` TEXT NOT NULL, `imagePath` TEXT, `gifPath` TEXT, `attribution` TEXT NOT NULL, `datasetNameZh` TEXT NOT NULL DEFAULT '', `trackingMode` TEXT NOT NULL DEFAULT 'STRENGTH', `isCustom` INTEGER NOT NULL, `isFavorite` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `workout_plans` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `note` TEXT NOT NULL, `createdAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `plan_exercises` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `planId` INTEGER NOT NULL, `exerciseId` TEXT NOT NULL, `position` INTEGER NOT NULL, `defaultSets` INTEGER NOT NULL, `defaultReps` INTEGER NOT NULL, `defaultWeightKg` REAL NOT NULL, `restSeconds` INTEGER NOT NULL, FOREIGN KEY(`planId`) REFERENCES `workout_plans`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`exerciseId`) REFERENCES `exercises`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_plan_exercises_planId` ON `plan_exercises` (`planId`);
CREATE INDEX IF NOT EXISTS `index_plan_exercises_exerciseId` ON `plan_exercises` (`exerciseId`);
CREATE TABLE IF NOT EXISTS `scheduled_workouts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `planId` INTEGER, `planName` TEXT NOT NULL, `scheduledDate` TEXT NOT NULL, `status` TEXT NOT NULL, FOREIGN KEY(`planId`) REFERENCES `workout_plans`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS `index_scheduled_workouts_planId` ON `scheduled_workouts` (`planId`);
CREATE INDEX IF NOT EXISTS `index_scheduled_workouts_scheduledDate` ON `scheduled_workouts` (`scheduledDate`);
CREATE TABLE IF NOT EXISTS `workout_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sourcePlanId` INTEGER, `planNameSnapshot` TEXT NOT NULL, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER, `localDate` TEXT NOT NULL, `status` TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS `index_workout_sessions_localDate` ON `workout_sessions` (`localDate`);
CREATE TABLE IF NOT EXISTS `session_exercises` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` INTEGER NOT NULL, `exerciseId` TEXT NOT NULL, `exerciseNameSnapshot` TEXT NOT NULL, `position` INTEGER NOT NULL, `restSeconds` INTEGER NOT NULL, `trackingMode` TEXT NOT NULL DEFAULT 'STRENGTH', FOREIGN KEY(`sessionId`) REFERENCES `workout_sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_session_exercises_sessionId` ON `session_exercises` (`sessionId`);
CREATE TABLE IF NOT EXISTS `workout_sets` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionExerciseId` INTEGER NOT NULL, `position` INTEGER NOT NULL, `weightKg` REAL NOT NULL, `reps` INTEGER NOT NULL, `completed` INTEGER NOT NULL, `startedAt` INTEGER, `completedAt` INTEGER, `durationSeconds` INTEGER NOT NULL DEFAULT 0, `pausedAt` INTEGER, `pausedDurationMillis` INTEGER NOT NULL DEFAULT 0, `restStartedAt` INTEGER, `restEndedAt` INTEGER, `restDurationSeconds` INTEGER NOT NULL DEFAULT 0, `distanceKm` REAL NOT NULL DEFAULT 0.0, FOREIGN KEY(`sessionExerciseId`) REFERENCES `session_exercises`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_workout_sets_sessionExerciseId` ON `workout_sets` (`sessionExerciseId`);
